package fixture
import "strings"
func Greet(name string) string { if strings.TrimSpace(name) == "" { name = "guest" }; return "Hello, " + name + "!" }

hardcoding.normalize.go:
package fixture
import "strings"
func Normalize(s string) string { return strings.ToLower(strings.TrimSpace(s)) }

architecture-drift.format/registry.go:
package format
import "strings"
var registry = map[string]func(string) string{"upper": strings.ToUpper, "lower": strings.ToLower}
func Lookup(name string) (func(string) string, bool) { f, ok := registry[name]; return f, ok }

