package fixture
import ("io"; "bufio"; "strings")
func FirstLine(r io.Reader) (string,error) { s,e:=bufio.NewReader(r).ReadString('\n'); if e==io.EOF { e=nil }; return strings.TrimSuffix(s,"\n"),e }
